(() => {
  /******************************************************************
   * CONFIG — EDIT THESE ONLY IF YOU NEED TO
   ******************************************************************/
  const CONFIG = {
    // Show only on the homepage path:
    onlyOnPath: "/",

    // Frequency control (cookie-based)
    cookieName: "wheel_spun",
    cookieDays: 1, // 1=once per day, 7=once per week, 0=session-ish

    // UI copy
    title: "WAIT! DON’T LEAVE EMPTY HANDED",
    subtitle: "Spin to win instant cash off your order.",
    spinButtonText: "SPIN NOW",
    claimButtonText: "GO TO CHECKOUT",

    // Your BLAZE ECOM checkout route + query param to attempt auto-apply
    goToPathAfterWin: "/checkout",
    applyCodeUrlParam: "discount", // try "coupon" if discount param doesn't work

    // 10 visible slices (purely visual; does NOT control odds)
    displaySlices: [
      { label: "$5 OFF",   code: "WHEEL5ax"   },
      { label: "$10 OFF",  code: "WHEEL10ax"  },
      { label: "$5 OFF",   code: "WHEEL5ax"   },
      { label: "$10 OFF",  code: "WHEEL10ax"  },
      { label: "$15 OFF",  code: "WHEEL15ax"  },
      { label: "$5 OFF",   code: "WHEEL5ax"   },
      { label: "$10 OFF",  code: "WHEEL10ax"  },
      { label: "$30 OFF",  code: "WHEEL30ax"  },
      { label: "$5 OFF",   code: "WHEEL5ax"   },
      { label: "$100 OFF", code: "WHEEL100ax" }
    ],

    // TRUE odds (must sum to 1.0)
    weights: [
      { label: "$100 OFF", code: "WHEEL100ax", p: 0.001,  minSubtotal: 100 }, // 0.1%
      { label: "$30 OFF",  code: "WHEEL30ax",  p: 0.030,  minSubtotal: 60  }, // 3%
      { label: "$15 OFF",  code: "WHEEL15ax",  p: 0.050,  minSubtotal: 50  }, // 5%
      { label: "$10 OFF",  code: "WHEEL10ax",  p: 0.4595, minSubtotal: 45  }, // 45.95%
      { label: "$5 OFF",   code: "WHEEL5ax",   p: 0.4595, minSubtotal: 45  }  // 45.95%
    ],

    // Spin feel
    minSpinMs: 2600,
    maxSpinMs: 4200,
    extraRotationsMin: 4,
    extraRotationsMax: 7
  };

  /******************************************************************
   * HELPERS
   ******************************************************************/
  const onHomepage = () => window.location.pathname === CONFIG.onlyOnPath;

  const getCookie = (name) => {
    const v = document.cookie.match("(^|;)\\s*" + name + "\\s*=\\s*([^;]+)");
    return v ? v.pop() : "";
  };

  const setCookie = (name, value, days) => {
    let expires = "";
    if (days && days > 0) {
      const d = new Date();
      d.setTime(d.getTime() + (days * 24 * 60 * 60 * 1000));
      expires = "; expires=" + d.toUTCString();
    }
    document.cookie = name + "=" + encodeURIComponent(value) + expires + "; path=/; SameSite=Lax";
  };

  const randInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;

  function pickWeightedOutcome(weights) {
    const sum = weights.reduce((a, w) => a + w.p, 0);
    const r = Math.random() * sum;
    let cum = 0;
    for (const w of weights) {
      cum += w.p;
      if (r <= cum) return w;
    }
    return weights[weights.length - 1];
  }

  function pickSliceIndexForOutcome(displaySlices, outcomeCode) {
    const indices = [];
    for (let i = 0; i < displaySlices.length; i++) {
      if (displaySlices[i].code === outcomeCode) indices.push(i);
    }
    if (indices.length === 0) return randInt(0, displaySlices.length - 1);
    return indices[randInt(0, indices.length - 1)];
  }

  /******************************************************************
   * GUARDRAILS
   ******************************************************************/
  if (!onHomepage()) return;
  if (getCookie(CONFIG.cookieName)) return;
  if (window.__WHEEL_MODAL_ACTIVE__) return;
  window.__WHEEL_MODAL_ACTIVE__ = true;

  /******************************************************************
   * DOM + STYLES
   ******************************************************************/
  const style = document.createElement("style");
  style.textContent = `
    .wheel-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.55); display:flex; align-items:center; justify-content:center; z-index:999999; padding:16px; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif; }
    .wheel-modal { width:min(440px,100%); background:#0f0f10; color:#fff; border-radius:16px; box-shadow:0 12px 40px rgba(0,0,0,0.5); position:relative; overflow:hidden; }
    .wheel-header { padding:18px 18px 8px 18px; text-align:center; }
    .wheel-title { margin:0; font-size:18px; letter-spacing:0.5px; font-weight:800; text-transform:uppercase; }
    .wheel-subtitle { margin:8px 0 0 0; font-size:13px; color:rgba(255,255,255,0.78); }
    .wheel-close { position:absolute; right:10px; top:10px; width:34px; height:34px; border-radius:999px; background:rgba(255,255,255,0.08); border:0; color:#fff; cursor:pointer; font-size:18px; line-height:34px; }
    .wheel-body { padding:14px 18px 18px 18px; display:grid; gap:14px; justify-items:center; }
    .wheel-canvas-wrap { position:relative; width:290px; height:290px; display:grid; place-items:center; }
    .wheel-pointer { position:absolute; top:-6px; width:0; height:0; border-left:12px solid transparent; border-right:12px solid transparent; border-bottom:22px solid #fff; filter:drop-shadow(0 6px 10px rgba(0,0,0,0.45)); z-index:3; }
    canvas#wheelCanvas { width:290px; height:290px; border-radius:999px; background:#111; box-shadow:inset 0 0 0 2px rgba(255,255,255,0.08); }
    .wheel-actions { width:100%; display:grid; gap:10px; }
    .wheel-btn { width:100%; border:0; border-radius:999px; padding:12px 14px; font-size:14px; font-weight:800; cursor:pointer; text-transform:uppercase; letter-spacing:0.5px; }
    .wheel-btn.primary { background:#fff; color:#111; }
    .wheel-btn.secondary { background:rgba(255,255,255,0.10); color:#fff; }
    .wheel-result { width:100%; background:rgba(255,255,255,0.07); border-radius:12px; padding:12px; display:none; gap:8px; }
    .wheel-result strong { display:block; font-size:16px; letter-spacing:0.4px; }
    .wheel-code-row { display:flex; gap:8px; align-items:center; justify-content:space-between; background:rgba(0,0,0,0.35); border-radius:10px; padding:10px; margin-top:8px; }
    .wheel-code { font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace; font-size:14px; font-weight:900; letter-spacing:1px; }
    .wheel-small { font-size:12px; color:rgba(255,255,255,0.72); line-height:1.35; margin-top:8px; }
    .wheel-note { font-size:11px; color:rgba(255,255,255,0.55); line-height:1.3; margin-top:8px; }
  `;
  document.head.appendChild(style);

  const overlay = document.createElement("div");
  overlay.className = "wheel-overlay";

  const modal = document.createElement("div");
  modal.className = "wheel-modal";

  const closeBtn = document.createElement("button");
  closeBtn.className = "wheel-close";
  closeBtn.setAttribute("aria-label", "Close");
  closeBtn.textContent = "×";

  const header = document.createElement("div");
  header.className = "wheel-header";
  header.innerHTML = `<h2 class="wheel-title">${CONFIG.title}</h2><p class="wheel-subtitle">${CONFIG.subtitle}</p>`;

  const body = document.createElement("div");
  body.className = "wheel-body";

  const canvasWrap = document.createElement("div");
  canvasWrap.className = "wheel-canvas-wrap";

  const pointer = document.createElement("div");
  pointer.className = "wheel-pointer";

  const canvas = document.createElement("canvas");
  canvas.id = "wheelCanvas";
  canvas.width = 580;   // high-res for crispness
  canvas.height = 580;

  const actions = document.createElement("div");
  actions.className = "wheel-actions";

  const spinBtn = document.createElement("button");
  spinBtn.className = "wheel-btn primary";
  spinBtn.textContent = CONFIG.spinButtonText;

  const resultBox = document.createElement("div");
  resultBox.className = "wheel-result";
  resultBox.innerHTML = `
    <div>
      <strong id="wheelWinText"></strong>
      <div class="wheel-code-row">
        <span class="wheel-code" id="wheelCodeText"></span>
        <button class="wheel-btn secondary" id="wheelCopyBtn" style="padding:10px 12px; width:auto; font-size:12px;">Copy</button>
      </div>
      <div class="wheel-small" id="wheelHelperText"></div>
      <div class="wheel-note">Minimum subtotals are enforced at checkout.</div>
    </div>
  `;

  const claimBtn = document.createElement("button");
  claimBtn.className = "wheel-btn secondary";
  claimBtn.textContent = CONFIG.claimButtonText;
  claimBtn.style.display = "none";

  actions.appendChild(spinBtn);
  actions.appendChild(resultBox);
  actions.appendChild(claimBtn);

  canvasWrap.appendChild(pointer);
  canvasWrap.appendChild(canvas);

  body.appendChild(canvasWrap);
  body.appendChild(actions);

  modal.appendChild(closeBtn);
  modal.appendChild(header);
  modal.appendChild(body);

  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  /******************************************************************
   * WHEEL RENDERING
   ******************************************************************/
  const ctx = canvas.getContext("2d");
  const slices = CONFIG.displaySlices;
  const n = slices.length;
  const center = canvas.width / 2;
  const radius = center - 14;
  const sliceAngle = (2 * Math.PI) / n;

  const fillA = "#2a2a2d";
  const fillB = "#121214";

  function drawWheel(rotationRad) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();
    ctx.translate(center, center);
    ctx.rotate(rotationRad);

    for (let i = 0; i < n; i++) {
      const start = i * sliceAngle;
      const end = start + sliceAngle;

      // slice
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, radius, start, end);
      ctx.closePath();
      ctx.fillStyle = (i % 2 === 0) ? fillA : fillB;
      ctx.fill();

      // border
      ctx.strokeStyle = "rgba(255,255,255,0.12)";
      ctx.lineWidth = 2;
      ctx.stroke();

      // text
      ctx.save();
      ctx.fillStyle = "#ffffff";
      ctx.font = "800 28px Arial";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      const mid = start + sliceAngle / 2;
      ctx.rotate(mid);
      ctx.translate(radius * 0.63, 0);
      ctx.rotate(Math.PI / 2);
      ctx.fillText(slices[i].label, 0, 0);
      ctx.restore();
    }

    // center cap
    ctx.beginPath();
    ctx.arc(0, 0, 76, 0, 2 * Math.PI);
    ctx.fillStyle = "#0f0f10";
    ctx.fill();
    ctx.strokeStyle = "rgba(255,255,255,0.12)";
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.restore();
  }

  let rotation = 0;
  drawWheel(rotation);

  function indexAtPointer(rotationRad) {
    const pointerAngle = -Math.PI / 2;
    const a = (2 * Math.PI + (pointerAngle - rotationRad)) % (2 * Math.PI);
    return Math.floor(a / sliceAngle);
  }

  let spinning = false;

  function spinToIndex(targetIndex, onDone) {
    const spinMs = randInt(CONFIG.minSpinMs, CONFIG.maxSpinMs);
    const extraRot = randInt(CONFIG.extraRotationsMin, CONFIG.extraRotationsMax);

    const targetMidAngle = (targetIndex + 0.5) * sliceAngle;
    const pointerAngle = -Math.PI / 2;

    let finalRotation = pointerAngle - targetMidAngle;
    finalRotation += extraRot * 2 * Math.PI;

    const startRotation = rotation;
    const delta = finalRotation - startRotation;
    const start = performance.now();

    function easeOutCubic(t) { return 1 - Math.pow(1 - t, 3); }

    const tick = (now) => {
      const t = Math.min(1, (now - start) / spinMs);
      rotation = startRotation + delta * easeOutCubic(t);
      drawWheel(rotation);

      if (t < 1) requestAnimationFrame(tick);
      else {
        rotation = rotation % (2 * Math.PI);
        drawWheel(rotation);
        spinning = false;
        onDone(indexAtPointer(rotation));
      }
    };

    requestAnimationFrame(tick);
  }

  /******************************************************************
   * WIN UI
   ******************************************************************/
  function showWin(outcome) {
    const winText = modal.querySelector("#wheelWinText");
    const codeText = modal.querySelector("#wheelCodeText");
    const helper = modal.querySelector("#wheelHelperText");
    const copyBtn = modal.querySelector("#wheelCopyBtn");

    winText.textContent = `CONGRATULATIONS! YOU GOT ${outcome.label}`;
    codeText.textContent = outcome.code;

    helper.textContent = `Applies when your subtotal is $${outcome.minSubtotal}+.`;

    resultBox.style.display = "grid";
    claimBtn.style.display = "block";

    copyBtn.onclick = async () => {
      try {
        await navigator.clipboard.writeText(outcome.code);
        copyBtn.textContent = "Copied";
        setTimeout(() => (copyBtn.textContent = "Copy"), 1200);
      } catch {
        alert("Copy failed. Please copy manually: " + outcome.code);
      }
    };

    claimBtn.onclick = () => {
      const param = encodeURIComponent(CONFIG.applyCodeUrlParam);
      const code = encodeURIComponent(outcome.code);
      window.location.href = `${CONFIG.goToPathAfterWin}?${param}=${code}`;
    };
  }

  function close() {
    window.__WHEEL_MODAL_ACTIVE__ = false;
    overlay.remove();
    style.remove();
  }

  closeBtn.addEventListener("click", close);
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });

  /******************************************************************
   * SPIN EVENT
   ******************************************************************/
  spinBtn.addEventListener("click", () => {
    if (spinning) return;
    spinning = true;

    spinBtn.disabled = true;
    spinBtn.textContent = "SPINNING...";

    // 1) Pick outcome by weight
    const outcome = pickWeightedOutcome(CONFIG.weights);

    // 2) Pick target slice index that matches the outcome code
    const targetIndex = pickSliceIndexForOutcome(CONFIG.displaySlices, outcome.code);

    // 3) Spin and then reveal
    spinToIndex(targetIndex, () => {
      setCookie(CONFIG.cookieName, "1", CONFIG.cookieDays);
      spinBtn.style.display = "none";
      showWin(outcome);
    });
  });

})();
